<?php
namespace ExcelHerbal\ERP7\Finance;
use ExcelHerbal\ERP7\Core\Input;use ExcelHerbal\ERP7\Database\Db;use ExcelHerbal\ERP7\Database\Transaction;use ExcelHerbal\ERP7\Domain\DomainException;use ExcelHerbal\ERP7\Inventory\StockService;use ExcelHerbal\ERP7\Security\Actor;use ExcelHerbal\ERP7\Security\Audit;use ExcelHerbal\ERP7\Security\Capabilities;use ExcelHerbal\ERP7\Security\Guard;
final class FinanceService{
 public static function bootstrap(Actor $a):array{Guard::any($a,[Capabilities::FINANCE_VIEW,Capabilities::ACCOUNT_MANAGE,Capabilities::SALES_CREATE,Capabilities::RECEIPT_CREATE,Capabilities::SUPPLIER_PAYMENT,Capabilities::EXPENSE_CREATE,Capabilities::BANK_RECONCILE,Capabilities::PAYROLL_PAY]);$db=Db::wpdb();return['accounts'=>(array)$db->get_results($db->prepare("SELECT id,code,name,type,subtype FROM ".Db::table('accounts')." WHERE company_id=%d AND active=1 ORDER BY code",$a->companyId),ARRAY_A),'expense_heads'=>(array)$db->get_results($db->prepare("SELECT id,code,name,expense_account_id FROM ".Db::table('expense_heads')." WHERE company_id=%d AND active=1 ORDER BY name",$a->companyId),ARRAY_A)];}
 public static function createAccount(Actor $a,string $code,string $name,string $type,string $subtype=''):array{Guard::cap($a,Capabilities::ACCOUNT_MANAGE);$code=strtoupper(trim($code));$name=trim($name);$type=strtolower(trim($type));$subtype=strtolower(trim($subtype));if($code===''||$name===''||!in_array($type,['asset','liability','equity','income','expense'],true))throw new DomainException('Valid account code, name and type are required.','account_fields_invalid',422);if(in_array($subtype,['cash','bank','upi'],true)&&$type!=='asset')throw new DomainException('Cash, Bank and UPI ledgers must be Asset accounts.','payment_account_type_invalid',422);$db=Db::wpdb();Db::mustInsert($db,Db::table('accounts'),['company_id'=>$a->companyId,'code'=>$code,'name'=>$name,'type'=>$type,'subtype'=>$subtype?:null,'active'=>1],'Account code already exists.','account_duplicate');$id=(int)$db->insert_id;Audit::add($a,'account.create','account',$id,['code'=>$code,'type'=>$type,'subtype'=>$subtype]);return['id'=>$id,'code'=>$code,'name'=>$name,'type'=>$type,'subtype'=>$subtype?:null];}
 public static function createExpenseHead(Actor $a,string $code,string $name,int $accountId):array{Guard::cap($a,Capabilities::ACCOUNT_MANAGE);$code=strtoupper(trim($code));$name=trim($name);if($code===''||$name===''||$accountId<1)throw new DomainException('Expense head code, name and expense account are required.','expense_head_fields_invalid',422);$account=AccountingService::account($a,$accountId);if((string)$account['type']!=='expense')throw new DomainException('Expense Head must point to an Expense ledger.','expense_head_account_invalid',422);$db=Db::wpdb();Db::mustInsert($db,Db::table('expense_heads'),['company_id'=>$a->companyId,'code'=>$code,'name'=>$name,'expense_account_id'=>$accountId,'active'=>1],'Expense Head code already exists.','expense_head_duplicate');$id=(int)$db->insert_id;Audit::add($a,'expense_head.create','expense_head',$id,['code'=>$code,'expense_account_id'=>$accountId]);return['id'=>$id,'code'=>$code,'name'=>$name,'expense_account_id'=>$accountId];}
 public static function expenses(Actor $a,int $branch):array{Guard::any($a,[Capabilities::EXPENSE_CREATE,Capabilities::EXPENSE_APPROVE,Capabilities::FINANCE_VIEW]);if(!$a->hasBranch($branch))throw new DomainException('Branch is outside effective authority.','branch_forbidden',403);$db=Db::wpdb();return(array)$db->get_results($db->prepare("SELECT e.*,h.name expense_head,a.code payment_account_code,a.name payment_account_name FROM ".Db::table('expenses')." e JOIN ".Db::table('expense_heads')." h ON h.id=e.expense_head_id JOIN ".Db::table('accounts')." a ON a.id=e.payment_account_id WHERE e.company_id=%d AND e.branch_id=%d ORDER BY e.id DESC LIMIT 200",$a->companyId,$branch),ARRAY_A);}
 public static function closings(Actor $a,int $branch):array{Guard::branch($a,$branch,$a->can(Capabilities::BRANCH_CLOSE)?Capabilities::BRANCH_CLOSE:Capabilities::BRANCH_REOPEN);$db=Db::wpdb();return(array)$db->get_results($db->prepare("SELECT * FROM ".Db::table('branch_closings')." WHERE company_id=%d AND branch_id=%d ORDER BY business_date DESC,id DESC LIMIT 200",$a->companyId,$branch),ARRAY_A);}
 public static function periods(Actor $a):array{Guard::allActiveBranches($a,Capabilities::PERIOD_MANAGE);$db=Db::wpdb();return(array)$db->get_results($db->prepare("SELECT * FROM ".Db::table('accounting_periods')." WHERE company_id=%d ORDER BY period_end DESC,id DESC LIMIT 100",$a->companyId),ARRAY_A);}
 public static function bankReconciliations(Actor $a,int $branch):array{Guard::branch($a,$branch,Capabilities::BANK_RECONCILE);$db=Db::wpdb();return(array)$db->get_results($db->prepare("SELECT r.*,a.code account_code,a.name account_name,(SELECT COUNT(*) FROM ".Db::table('bank_statement_lines')." l WHERE l.reconciliation_id=r.id AND l.status='unmatched') unmatched_lines FROM ".Db::table('bank_reconciliations')." r JOIN ".Db::table('accounts')." a ON a.id=r.bank_account_id WHERE r.company_id=%d AND r.branch_id=%d ORDER BY r.id DESC LIMIT 200",$a->companyId,$branch),ARRAY_A);}
 public static function expense(Actor $a,int $branch,int $head,float $amount,int $account,string $date,string $desc):array{$date=Input::date($date,'Expense date');$amount=round($amount,2);Guard::branch($a,$branch,Capabilities::EXPENSE_CREATE);BranchDayGuard::assertOpen($a,$branch,$date);if($amount<=0)throw new DomainException('Expense amount must be positive.');AccountingService::paymentAccount($a,$account);$db=Db::wpdb();if(!(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM ".Db::table('expense_heads')." WHERE id=%d AND company_id=%d AND active=1",$head,$a->companyId)))throw new DomainException('Expense head not found.');Db::mustInsert($db,Db::table('expenses'),['company_id'=>$a->companyId,'branch_id'=>$branch,'expense_head_id'=>$head,'amount'=>$amount,'payment_account_id'=>$account,'status'=>'pending','expense_date'=>$date,'description'=>$desc,'created_by'=>$a->employeeId,'created_at'=>Db::now()]);$id=(int)$db->insert_id;Audit::add($a,'expense.create','expense',$id,['branch_id'=>$branch]);return['id'=>$id,'status'=>'pending'];}
 public static function expenseDecision(Actor $a,int $id,bool $approve):array{return Transaction::run(function()use($a,$id,$approve){$db=Db::wpdb();$t=Db::table('expenses');$r=$db->get_row($db->prepare("SELECT * FROM {$t} WHERE id=%d AND company_id=%d FOR UPDATE",$id,$a->companyId),ARRAY_A);if(!$r)throw new DomainException('Expense not found.','expense_not_found',404);Guard::branch($a,(int)$r['branch_id'],Capabilities::EXPENSE_APPROVE);BranchDayGuard::assertOpen($a,(int)$r['branch_id'],(string)$r['expense_date']);if($r['status']!=='pending')throw new DomainException('Expense not pending.');if((int)$r['created_by']===$a->employeeId)throw new DomainException('Maker cannot approve own expense.','maker_checker_required',409);$status=$approve?'approved':'rejected';$journal=null;if($approve){$head=$db->get_row($db->prepare("SELECT * FROM ".Db::table('expense_heads')." WHERE id=%d",(int)$r['expense_head_id']),ARRAY_A);$journal=AccountingService::post($a,(int)$r['branch_id'],'expense',$id,$r['expense_date'].' 12:00:00',[['account_id'=>(int)$head['expense_account_id'],'debit'=>(float)$r['amount']],['account_id'=>(int)$r['payment_account_id'],'credit'=>(float)$r['amount']]],'Expense approval');}Db::mustUpdate($db,$t,['status'=>$status,'approved_by'=>$a->employeeId,'approved_at'=>Db::now(),'journal_entry_id'=>$journal],['id'=>$id]);return['id'=>$id,'status'=>$status,'journal_entry_id'=>$journal];});}
 public static function closingPreflight(Actor $a,int $branch,string $date):array{$date=Input::date($date,'Business date');Guard::branch($a,$branch,Capabilities::BRANCH_CLOSE);$db=Db::wpdb();$checks=['daily_cycles_open'=>(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM ".Db::table('daily_cycles')." WHERE company_id=%d AND branch_id=%d AND business_date=%s AND status NOT IN ('completed','cancelled')",$a->companyId,$branch,$date)),'transfers_open'=>(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM ".Db::table('stock_transfers')." WHERE company_id=%d AND (source_branch_id=%d OR destination_branch_id=%d) AND status NOT IN ('received','cancelled')",$a->companyId,$branch,$branch)),'adjustments_pending'=>(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM ".Db::table('stock_adjustments')." WHERE company_id=%d AND branch_id=%d AND status='pending'",$a->companyId,$branch)),'quarantine_open'=>(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM ".Db::table('stock_quarantine')." WHERE company_id=%d AND branch_id=%d AND status='open'",$a->companyId,$branch)),'expenses_pending'=>(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM ".Db::table('expenses')." WHERE company_id=%d AND branch_id=%d AND status='pending' AND expense_date<=%s",$a->companyId,$branch,$date)),'reversals_pending'=>(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM ".Db::table('reversals')." WHERE company_id=%d AND status IN ('pending','approved') AND (branch_id=%d OR branch_id IS NULL)",$a->companyId,$branch)),'payroll_draft'=>(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM ".Db::table('payroll_runs')." WHERE company_id=%d AND branch_id=%d AND status='draft' AND period_end<=%s",$a->companyId,$branch,$date)),'employee_custody_nonzero'=>(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM ".Db::table('stock_balances')." WHERE company_id=%d AND branch_id=%d AND custodian_key>0 AND ABS(quantity)>.0001",$a->companyId,$branch)),'negative_stock'=>(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM ".Db::table('stock_balances')." WHERE company_id=%d AND branch_id=%d AND quantity<-.0001",$a->companyId,$branch))];$blocking=array_keys(array_filter($checks,fn($v)=>(int)$v>0));return['ok'=>!$blocking,'checks'=>$checks,'blocking'=>$blocking];}
 public static function closingDraft(Actor $a,int $branch,string $date):array{$date=Input::date($date,'Business date');Guard::branch($a,$branch,Capabilities::BRANCH_CLOSE);return Transaction::run(function()use($a,$branch,$date){$db=Db::wpdb();$branchTable=Db::table('branches');$locked=$db->get_var($db->prepare("SELECT id FROM {$branchTable} WHERE id=%d AND company_id=%d AND status='active' FOR UPDATE",$branch,$a->companyId));if(!$locked)throw new DomainException('Active branch not found.','branch_not_found',404);$t=Db::table('branch_closings');$r=$db->get_row($db->prepare("SELECT * FROM {$t} WHERE company_id=%d AND branch_id=%d AND business_date=%s FOR UPDATE",$a->companyId,$branch,$date),ARRAY_A);if($r)return['id'=>(int)$r['id'],'status'=>$r['status']];Db::mustInsert($db,$t,['company_id'=>$a->companyId,'branch_id'=>$branch,'business_date'=>$date,'status'=>'draft','created_by'=>$a->employeeId,'created_at'=>Db::now()]);return['id'=>(int)$db->insert_id,'status'=>'draft'];});}
 public static function closeBranch(Actor $a,int $id):array{return Transaction::run(function()use($a,$id){$db=Db::wpdb();$t=Db::table('branch_closings');$r=$db->get_row($db->prepare("SELECT * FROM {$t} WHERE id=%d AND company_id=%d FOR UPDATE",$id,$a->companyId),ARRAY_A);if(!$r)throw new DomainException('Branch closing not found.','closing_not_found',404);Guard::branch($a,(int)$r['branch_id'],Capabilities::BRANCH_CLOSE);if((int)$r['created_by']===$a->employeeId)throw new DomainException('Maker cannot close own draft.','maker_checker_required',409);$pf=self::closingPreflight($a,(int)$r['branch_id'],(string)$r['business_date']);if(!$pf['ok'])throw new DomainException('Closing blocked: '.implode(', ',$pf['blocking']),'closing_blocked',409);Db::mustUpdate($db,$t,['status'=>'closed','preflight_json'=>wp_json_encode($pf),'closed_by'=>$a->employeeId,'closed_at'=>Db::now()],['id'=>$id]);return['id'=>$id,'status'=>'closed','preflight'=>$pf];});}
 public static function reopenBranch(Actor $a,int $id,string $reason):array{Guard::cap($a,Capabilities::BRANCH_REOPEN);if(strlen(trim($reason))<5)throw new DomainException('Reopen reason required.');$db=Db::wpdb();$t=Db::table('branch_closings');$r=$db->get_row($db->prepare("SELECT * FROM {$t} WHERE id=%d AND company_id=%d",$id,$a->companyId),ARRAY_A);if(!$r)throw new DomainException('Closing not found.');Guard::branch($a,(int)$r['branch_id'],Capabilities::BRANCH_REOPEN);if($r['status']!=='closed')throw new DomainException('Only closed day can reopen.');Db::mustUpdate($db,$t,['status'=>'reopened','reopened_by'=>$a->employeeId,'reopened_at'=>Db::now()],['id'=>$id]);Audit::add($a,'branch_closing.reopen','branch_closing',$id,['branch_id'=>(int)$r['branch_id'],'reason'=>$reason]);return['id'=>$id,'status'=>'reopened'];}
 public static function reversals(Actor $a,string $status=''):array{Guard::any($a,[Capabilities::REVERSAL_CREATE,Capabilities::REVERSAL_APPROVE]);$db=Db::wpdb();$sql="SELECT * FROM ".Db::table('reversals')." WHERE company_id=%d";$args=[$a->companyId];if($status!==''){$sql.=' AND status=%s';$args[]=$status;}$sql.=' ORDER BY id DESC LIMIT 200';return(array)$db->get_results($db->prepare($sql,...$args),ARRAY_A);}
 public static function requestReversal(Actor $a,string $type,int $source,string $reason):array{Guard::cap($a,Capabilities::REVERSAL_CREATE);$allowed=['counter_sale','purchase_bill','supplier_payment','customer_receipt','expense','daily_cycle','stock_adjustment','payroll','payroll_payment'];if(!in_array($type,$allowed,true)||$source<1||strlen(trim($reason))<5)throw new DomainException('Valid source and reason required.');return Transaction::run(function()use($a,$type,$source,$reason){$db=Db::wpdb();$map=['counter_sale'=>'counter_sales','purchase_bill'=>'purchase_bills','supplier_payment'=>'supplier_payments','customer_receipt'=>'customer_receipts','expense'=>'expenses','daily_cycle'=>'daily_cycles','stock_adjustment'=>'stock_adjustments','payroll'=>'payroll_runs','payroll_payment'=>'payroll_runs'];$sourceRow=$db->get_row($db->prepare("SELECT * FROM ".Db::table($map[$type])." WHERE id=%d AND company_id=%d FOR UPDATE",$source,$a->companyId),ARRAY_A);if(!$sourceRow)throw new DomainException('Reversal source not found.','reversal_source_not_found',404);$branch=$sourceRow['branch_id']!==null?(int)$sourceRow['branch_id']:null;if($branch)Guard::branch($a,$branch,Capabilities::REVERSAL_CREATE);$status=(string)$sourceRow['status'];$required=in_array($type,['expense','stock_adjustment','payroll'],true)?'approved':($type==='payroll_payment'?'paid':($type==='daily_cycle'?'completed':'posted'));if($status!==$required)throw new DomainException('Only a currently posted/approved source can be reversed.','reversal_source_state_invalid',409);$active=(int)$db->get_var($db->prepare("SELECT id FROM ".Db::table('reversals')." WHERE company_id=%d AND source_type=%s AND source_id=%d AND status IN ('pending','approved') ORDER BY id DESC LIMIT 1 FOR UPDATE",$a->companyId,$type,$source));if($active)throw new DomainException('An active reversal request already exists for this source.','reversal_already_pending',409);Db::mustInsert($db,Db::table('reversals'),['company_id'=>$a->companyId,'branch_id'=>$branch,'source_type'=>$type,'source_id'=>$source,'reason'=>trim($reason),'status'=>'pending','requested_by'=>$a->employeeId,'requested_at'=>Db::now()]);$id=(int)$db->insert_id;Audit::add($a,'reversal.request','reversal',$id,['branch_id'=>$branch,'source_type'=>$type,'source_id'=>$source]);return['id'=>$id,'status'=>'pending'];});}
 public static function reversalDecision(Actor $a,int $id,bool $approve):array{
  Guard::cap($a,Capabilities::REVERSAL_APPROVE);
  return Transaction::run(function()use($a,$id,$approve){
   $db=Db::wpdb();$t=Db::table('reversals');$r=$db->get_row($db->prepare("SELECT * FROM {$t} WHERE id=%d AND company_id=%d FOR UPDATE",$id,$a->companyId),ARRAY_A);if(!$r)throw new DomainException('Reversal not found.');if($r['branch_id'])Guard::branch($a,(int)$r['branch_id'],Capabilities::REVERSAL_APPROVE);if($r['status']!=='pending')throw new DomainException('Reversal not pending.');if((int)$r['requested_by']===$a->employeeId)throw new DomainException('Maker cannot approve own reversal.','maker_checker_required',409);$status=$approve?'approved':'rejected';Db::mustUpdate($db,$t,['status'=>$status,'decided_by'=>$a->employeeId,'decided_at'=>Db::now()],['id'=>$id]);return['id'=>$id,'status'=>$status];
  });
 }
 public static function executeReversal(Actor $a,int $id):array{return Transaction::run(function()use($a,$id){$db=Db::wpdb();$t=Db::table('reversals');$r=$db->get_row($db->prepare("SELECT * FROM {$t} WHERE id=%d AND company_id=%d FOR UPDATE",$id,$a->companyId),ARRAY_A);if(!$r||$r['status']!=='approved')throw new DomainException('Approved reversal not found.');if($r['branch_id']){Guard::branch($a,(int)$r['branch_id'],Capabilities::REVERSAL_APPROVE);if((string)$r['source_type']!=='daily_cycle')BranchDayGuard::assertOpen($a,(int)$r['branch_id'],Db::today());}$type=(string)$r['source_type'];$source=(int)$r['source_id'];$journalId=self::sourceJournal($a,$type,$source);if(!$journalId)throw new DomainException('Source journal missing.','source_journal_missing',409);if($type==='counter_sale')self::reverseCounterStock($a,$source);elseif($type==='purchase_bill')self::reversePurchaseStock($a,$source);elseif($type==='supplier_payment')self::reverseSupplierPayment($a,$source);elseif($type==='customer_receipt')self::reverseCustomerReceipt($a,$source);elseif($type==='daily_cycle')self::reverseDailyCycle($a,$source,$id);elseif($type==='stock_adjustment')self::reverseStockAdjustment($a,$source,$id);$rev=AccountingService::reverse($a,$journalId,(string)$r['reason'],$id);self::markSourceReversed($type,$source);Db::mustUpdate($db,$t,['status'=>'executed','executed_by'=>$a->employeeId,'executed_at'=>Db::now()],['id'=>$id]);Audit::add($a,'reversal.execute','reversal',$id,['branch_id'=>$r['branch_id'],'source_type'=>$type,'source_id'=>$source]);return['id'=>$id,'status'=>'executed','reversal_journal_id'=>$rev];});}
 public static function closePeriod(Actor $a,string $from,string $to):array{
  Guard::allActiveBranches($a,Capabilities::PERIOD_MANAGE);
  [$from,$to]=Input::dateRange($from,$to,'Accounting period');
  return Transaction::run(function()use($a,$from,$to){
   $db=Db::wpdb();$periods=Db::table('accounting_periods');
   $existing=$db->get_row($db->prepare("SELECT * FROM {$periods} WHERE company_id=%d AND period_start=%s AND period_end=%s FOR UPDATE",$a->companyId,$from,$to),ARRAY_A);
   $overlap=(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM {$periods} WHERE company_id=%d AND status='closed' AND NOT(period_start=%s AND period_end=%s) AND NOT(period_end<%s OR period_start>%s)",$a->companyId,$from,$to,$from,$to));
   if($overlap)throw new DomainException('Period overlaps existing close.','period_overlap',409);
   $openDaily=(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM ".Db::table('daily_cycles')." WHERE company_id=%d AND business_date BETWEEN %s AND %s AND status NOT IN ('completed','cancelled')",$a->companyId,$from,$to));
   $pendingExpenses=(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM ".Db::table('expenses')." WHERE company_id=%d AND expense_date BETWEEN %s AND %s AND status='pending'",$a->companyId,$from,$to));
   $pendingAdjustments=(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM ".Db::table('stock_adjustments')." WHERE company_id=%d AND status='pending' AND DATE(created_at)<=%s",$a->companyId,$to));
   $pendingReversals=(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM ".Db::table('reversals')." WHERE company_id=%d AND status IN ('pending','approved') AND DATE(requested_at)<=%s",$a->companyId,$to));
   $draftPayroll=(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM ".Db::table('payroll_runs')." WHERE company_id=%d AND status='draft' AND period_end<=%s",$a->companyId,$to));
   $branches=Db::table('branches');$closings=Db::table('branch_closings');$daily=Db::table('daily_cycles');$journals=Db::table('journal_entries');
   $missingClosings=(array)$db->get_results($db->prepare(
    "SELECT x.branch_id,b.name branch_name,x.business_date
     FROM (
       SELECT branch_id,business_date FROM {$daily} WHERE company_id=%d AND business_date BETWEEN %s AND %s
       UNION
       SELECT branch_id,DATE(entry_date) business_date FROM {$journals} WHERE company_id=%d AND branch_id IS NOT NULL AND status='posted' AND DATE(entry_date) BETWEEN %s AND %s
       UNION
       SELECT id branch_id,%s business_date FROM {$branches} WHERE company_id=%d AND status='active'
     ) x
     JOIN {$branches} b ON b.id=x.branch_id AND b.company_id=%d AND b.status='active'
     LEFT JOIN {$closings} c ON c.company_id=%d AND c.branch_id=x.branch_id AND c.business_date=x.business_date AND c.status='closed'
     WHERE c.id IS NULL
     ORDER BY x.business_date,b.name",
    $a->companyId,$from,$to,$a->companyId,$from,$to,$to,$a->companyId,$a->companyId,$a->companyId
   ),ARRAY_A);
   $blocking=[];
   if($openDaily)$blocking[]='open_daily_cycles';
   if($pendingExpenses)$blocking[]='pending_expenses';
   if($pendingAdjustments)$blocking[]='pending_stock_adjustments';
   if($pendingReversals)$blocking[]='pending_reversals';
   if($draftPayroll)$blocking[]='draft_payroll';
   if($missingClosings){$refs=[];foreach(array_slice($missingClosings,0,20) as $m)$refs[]=$m['business_date'].' '.$m['branch_name'];$suffix=count($missingClosings)>20?' ...':'';$blocking[]='missing_branch_closings('.count($missingClosings).'): '.implode(', ',$refs).$suffix;}
   if($blocking)throw new DomainException('Accounting Period close blocked: '.implode('; ',$blocking),'period_close_blocked',409);
   $data=['status'=>'closed','closed_by'=>$a->employeeId,'closed_at'=>Db::now(),'reopened_by'=>null,'reopened_at'=>null];
   if($existing){if($existing['status']==='closed')return['id'=>(int)$existing['id'],'status'=>'closed'];Db::mustUpdate($db,$periods,$data,['id'=>(int)$existing['id']]);$id=(int)$existing['id'];}
   else{Db::mustInsert($db,$periods,['company_id'=>$a->companyId,'period_start'=>$from,'period_end'=>$to]+$data);if(!$db->insert_id)throw new DomainException('Accounting period could not be created.','period_create_failed',500);$id=(int)$db->insert_id;}
   Audit::add($a,'accounting_period.close','accounting_period',$id,['from'=>$from,'to'=>$to,'required_closings_verified'=>true]);
   return['id'=>$id,'status'=>'closed'];
  });
 }
 public static function reopenPeriod(Actor $a,int $id,string $reason):array{Guard::allActiveBranches($a,Capabilities::PERIOD_MANAGE);if(strlen(trim($reason))<5)throw new DomainException('Reason required.');$db=Db::wpdb();$t=Db::table('accounting_periods');$r=$db->get_row($db->prepare("SELECT * FROM {$t} WHERE id=%d AND company_id=%d",$id,$a->companyId),ARRAY_A);if(!$r||$r['status']!=='closed')throw new DomainException('Closed period not found.');Db::mustUpdate($db,$t,['status'=>'open','reopened_by'=>$a->employeeId,'reopened_at'=>Db::now()],['id'=>$id]);Audit::add($a,'accounting_period.reopen','accounting_period',$id,['reason'=>$reason,'from'=>$r['period_start'],'to'=>$r['period_end']]);return['id'=>$id,'status'=>'open'];}
 public static function bankDetail(Actor $a,int $id):array{$db=Db::wpdb();$r=$db->get_row($db->prepare("SELECT r.*,a.code account_code,a.name account_name FROM ".Db::table('bank_reconciliations')." r JOIN ".Db::table('accounts')." a ON a.id=r.bank_account_id WHERE r.id=%d AND r.company_id=%d",$id,$a->companyId),ARRAY_A);if(!$r)throw new DomainException('Bank reconciliation not found.','bank_reconciliation_not_found',404);Guard::branch($a,(int)$r['branch_id'],Capabilities::BANK_RECONCILE);$lines=(array)$db->get_results($db->prepare("SELECT * FROM ".Db::table('bank_statement_lines')." WHERE reconciliation_id=%d ORDER BY txn_date,id",$id),ARRAY_A);$candidates=(array)$db->get_results($db->prepare("SELECT jl.id journal_line_id,je.entry_no,je.entry_date,je.source_type,je.source_id,jl.debit,jl.credit,jl.description FROM ".Db::table('journal_lines')." jl JOIN ".Db::table('journal_entries')." je ON je.id=jl.journal_entry_id WHERE je.company_id=%d AND je.status='posted' AND je.branch_id=%d AND jl.account_id=%d AND DATE(je.entry_date) BETWEEN %s AND %s AND NOT EXISTS(SELECT 1 FROM ".Db::table('bank_statement_lines')." x WHERE x.matched_journal_line_id=jl.id AND x.status='matched') ORDER BY je.entry_date,je.id,jl.id",$a->companyId,(int)$r['branch_id'],(int)$r['bank_account_id'],$r['statement_from'],$r['statement_to']),ARRAY_A);return['reconciliation'=>$r,'lines'=>$lines,'journal_candidates'=>$candidates];}
 public static function bankCreate(Actor $a,int $branch,int $account,string $from,string $to,float $opening,float $closing):array{[$from,$to]=Input::dateRange($from,$to,'Bank statement period');$opening=round($opening,2);$closing=round($closing,2);Guard::branch($a,$branch,Capabilities::BANK_RECONCILE);AccountingService::bankAccount($a,$account);return Transaction::run(function()use($a,$branch,$account,$from,$to,$opening,$closing){$db=Db::wpdb();$accountTable=Db::table('accounts');$locked=$db->get_var($db->prepare("SELECT id FROM {$accountTable} WHERE id=%d AND company_id=%d AND active=1 FOR UPDATE",$account,$a->companyId));if(!$locked)throw new DomainException('Bank account not found.','bank_account_invalid',422);$overlap=(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM ".Db::table('bank_reconciliations')." WHERE company_id=%d AND bank_account_id=%d AND status IN ('draft','finalized') AND NOT(statement_to<%s OR statement_from>%s)",$a->companyId,$account,$from,$to));if($overlap)throw new DomainException('Overlapping bank reconciliation already exists for this account.','bank_reconciliation_overlap',409);Db::mustInsert($db,Db::table('bank_reconciliations'),['company_id'=>$a->companyId,'branch_id'=>$branch,'bank_account_id'=>$account,'statement_from'=>$from,'statement_to'=>$to,'opening_balance'=>$opening,'closing_balance'=>$closing,'status'=>'draft','created_by'=>$a->employeeId,'created_at'=>Db::now()]);$id=(int)$db->insert_id;Audit::add($a,'bank_reconciliation.create','bank_reconciliation',$id,['branch_id'=>$branch,'account_id'=>$account]);return['id'=>$id,'status'=>'draft'];});}
 public static function bankImport(Actor $a,int $id,array $lines):array{Guard::cap($a,Capabilities::BANK_RECONCILE);if(!$lines)throw new DomainException('Statement lines are required.');return Transaction::run(function()use($a,$id,$lines){$db=Db::wpdb();$h=Db::table('bank_reconciliations');$r=$db->get_row($db->prepare("SELECT * FROM {$h} WHERE id=%d AND company_id=%d FOR UPDATE",$id,$a->companyId),ARRAY_A);if(!$r||$r['status']!=='draft')throw new DomainException('Draft reconciliation not found.');Guard::branch($a,(int)$r['branch_id'],Capabilities::BANK_RECONCILE);$count=0;foreach($lines as$x){$dr=round((float)($x['debit']??0),2);$cr=round((float)($x['credit']??0),2);$date=Input::date((string)($x['txn_date']??''),'Bank transaction date');if($date<(string)$r['statement_from']||$date>(string)$r['statement_to'])throw new DomainException('Bank transaction date is outside the reconciliation period.','bank_line_date_outside_period',422);if(($dr>0)==($cr>0))throw new DomainException('Each statement line needs either debit or credit.');Db::mustInsert($db,Db::table('bank_statement_lines'),['reconciliation_id'=>$id,'txn_date'=>$date,'description'=>(string)($x['description']??''),'reference'=>(string)($x['reference']??''),'debit'=>$dr,'credit'=>$cr,'status'=>'unmatched']);$count++;}return['id'=>$id,'imported'=>$count];});}
 public static function bankMatch(Actor $a,int $line,int $journalLine):array{
  Guard::cap($a,Capabilities::BANK_RECONCILE);
  return Transaction::run(function()use($a,$line,$journalLine){
   $db=Db::wpdb();$l=$db->get_row($db->prepare("SELECT bl.*,r.company_id,r.branch_id,r.bank_account_id,r.statement_from,r.statement_to,r.status recon_status FROM ".Db::table('bank_statement_lines')." bl JOIN ".Db::table('bank_reconciliations')." r ON r.id=bl.reconciliation_id WHERE bl.id=%d AND r.company_id=%d FOR UPDATE",$line,$a->companyId),ARRAY_A);if(!$l||$l['recon_status']!=='draft'||$l['status']!=='unmatched')throw new DomainException('Unmatched bank line not found.');Guard::branch($a,(int)$l['branch_id'],Capabilities::BANK_RECONCILE);
   $j=$db->get_row($db->prepare("SELECT jl.*,je.status je_status,je.company_id,je.branch_id,je.entry_date FROM ".Db::table('journal_lines')." jl JOIN ".Db::table('journal_entries')." je ON je.id=jl.journal_entry_id WHERE jl.id=%d FOR UPDATE",$journalLine),ARRAY_A);if(!$j||(int)$j['company_id']!==$a->companyId||(int)$j['account_id']!==(int)$l['bank_account_id']||$j['je_status']!=='posted'||(int)$j['branch_id']!==(int)$l['branch_id'])throw new DomainException('Journal line not eligible for this branch/account.','bank_journal_scope_invalid',422);$journalDate=substr((string)$j['entry_date'],0,10);if($journalDate<(string)$l['statement_from']||$journalDate>(string)$l['statement_to'])throw new DomainException('Journal line is outside the reconciliation period.','bank_journal_date_outside_period',422);
   $already=(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM ".Db::table('bank_statement_lines')." WHERE matched_journal_line_id=%d AND status='matched' AND id<>%d",$journalLine,$line));if($already)throw new DomainException('Journal line is already matched to another statement line.','bank_journal_already_matched',409);$statement=round((float)$l['credit']-(float)$l['debit'],2);$journal=round((float)$j['debit']-(float)$j['credit'],2);if(abs($statement-$journal)>.005)throw new DomainException('Bank amount mismatch.');Db::mustUpdate($db,Db::table('bank_statement_lines'),['status'=>'matched','matched_journal_line_id'=>$journalLine],['id'=>$line]);return['id'=>$line,'status'=>'matched'];
  });
 }
 public static function bankExclude(Actor $a,int $line,string $reason):array{$reason=trim($reason);if(strlen($reason)<5)throw new DomainException('Reason required.');return Transaction::run(function()use($a,$line,$reason){$db=Db::wpdb();$l=$db->get_row($db->prepare("SELECT bl.*,r.company_id,r.branch_id,r.status recon_status FROM ".Db::table('bank_statement_lines')." bl JOIN ".Db::table('bank_reconciliations')." r ON r.id=bl.reconciliation_id WHERE bl.id=%d AND r.company_id=%d FOR UPDATE",$line,$a->companyId),ARRAY_A);if(!$l||$l['recon_status']!=='draft')throw new DomainException('Draft bank line not found.');Guard::branch($a,(int)$l['branch_id'],Capabilities::BANK_RECONCILE);$updated=$db->update(Db::table('bank_statement_lines'),['status'=>'excluded','matched_journal_line_id'=>null,'exclusion_reason'=>$reason,'excluded_by'=>$a->employeeId,'excluded_at'=>Db::now()],['id'=>$line]);if($updated===false)throw new DomainException('Bank line exclusion failed.','bank_line_store_failed',500);Audit::add($a,'bank_line.exclude','bank_statement_line',$line,['branch_id'=>(int)$l['branch_id'],'reason'=>$reason]);return['id'=>$line,'status'=>'excluded'];});}
 public static function bankFinalize(Actor $a,int $id):array{Guard::cap($a,Capabilities::BANK_RECONCILE);return Transaction::run(function()use($a,$id){$db=Db::wpdb();$t=Db::table('bank_reconciliations');$r=$db->get_row($db->prepare("SELECT * FROM {$t} WHERE id=%d AND company_id=%d FOR UPDATE",$id,$a->companyId),ARRAY_A);if(!$r||$r['status']!=='draft')throw new DomainException('Draft reconciliation not found.');Guard::branch($a,(int)$r['branch_id'],Capabilities::BANK_RECONCILE);$lineTable=Db::table('bank_statement_lines');$lineCount=(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM {$lineTable} WHERE reconciliation_id=%d",$id));if($lineCount<1)throw new DomainException('Import bank statement lines before finalizing.','bank_statement_required',409);if((int)$db->get_var($db->prepare("SELECT COUNT(*) FROM {$lineTable} WHERE reconciliation_id=%d AND status='unmatched'",$id)))throw new DomainException('Resolve all unmatched lines.','bank_unmatched',409);$totals=$db->get_row($db->prepare("SELECT COALESCE(SUM(credit),0) credits,COALESCE(SUM(debit),0) debits FROM {$lineTable} WHERE reconciliation_id=%d",$id),ARRAY_A);$calculated=round((float)$r['opening_balance']+(float)$totals['credits']-(float)$totals['debits'],2);if(abs($calculated-(float)$r['closing_balance'])>.005)throw new DomainException('Statement opening + credits - debits must equal closing balance.','bank_statement_balance_mismatch',409);$updated=$db->update($t,['status'=>'finalized','finalized_by'=>$a->employeeId,'finalized_at'=>Db::now()],['id'=>$id]);if($updated===false)throw new DomainException('Bank reconciliation finalize failed.','bank_reconciliation_store_failed',500);return['id'=>$id,'status'=>'finalized'];});}
 private static function sourceBranch(Actor $a,string $type,int $id):?int{$map=['counter_sale'=>'counter_sales','purchase_bill'=>'purchase_bills','supplier_payment'=>'supplier_payments','customer_receipt'=>'customer_receipts','expense'=>'expenses','daily_cycle'=>'daily_cycles','stock_adjustment'=>'stock_adjustments','payroll'=>'payroll_runs','payroll_payment'=>'payroll_runs'];$db=Db::wpdb();$r=$db->get_row($db->prepare("SELECT branch_id FROM ".Db::table($map[$type])." WHERE id=%d AND company_id=%d",$id,$a->companyId),ARRAY_A);if(!$r)throw new DomainException('Reversal source not found.');return$r['branch_id']!==null?(int)$r['branch_id']:null;}
 private static function sourceStatus(Actor $a,string $type,int $id):string{$map=['counter_sale'=>'counter_sales','purchase_bill'=>'purchase_bills','supplier_payment'=>'supplier_payments','customer_receipt'=>'customer_receipts','expense'=>'expenses','daily_cycle'=>'daily_cycles','stock_adjustment'=>'stock_adjustments','payroll'=>'payroll_runs','payroll_payment'=>'payroll_runs'];$db=Db::wpdb();$status=$db->get_var($db->prepare("SELECT status FROM ".Db::table($map[$type])." WHERE id=%d AND company_id=%d",$id,$a->companyId));if($status===null)throw new DomainException('Reversal source not found.','reversal_source_not_found',404);return(string)$status;}
 private static function sourceJournal(Actor $a,string $type,int $id):int{$map=['counter_sale'=>'counter_sales','purchase_bill'=>'purchase_bills','supplier_payment'=>'supplier_payments','customer_receipt'=>'customer_receipts','expense'=>'expenses','stock_adjustment'=>'stock_adjustments','payroll'=>'payroll_runs','payroll_payment'=>'payroll_runs'];if($type==='daily_cycle')return(int)Db::wpdb()->get_var(Db::wpdb()->prepare("SELECT id FROM ".Db::table('journal_entries')." WHERE company_id=%d AND source_type='daily_cycle' AND source_id=%d AND status='posted'",$a->companyId,$id));if($type==='payroll_payment')return(int)Db::wpdb()->get_var(Db::wpdb()->prepare("SELECT payment_journal_entry_id FROM ".Db::table('payroll_runs')." WHERE id=%d AND company_id=%d",$id,$a->companyId));return(int)Db::wpdb()->get_var(Db::wpdb()->prepare("SELECT journal_entry_id FROM ".Db::table($map[$type])." WHERE id=%d AND company_id=%d",$id,$a->companyId));}
 private static function markSourceReversed(string $type,int $id):void{$db=Db::wpdb();if($type==='payroll_payment'){Db::mustUpdate($db,Db::table('payroll_runs'),['status'=>'approved','payment_account_id'=>null,'payment_journal_entry_id'=>null,'payment_date'=>null,'paid_by'=>null,'paid_at'=>null],['id'=>$id]);return;}if($type==='payroll'){Db::mustUpdate($db,Db::table('payroll_runs'),['status'=>'draft','approved_by'=>null,'journal_entry_id'=>null,'approved_at'=>null],['id'=>$id]);return;}$map=['counter_sale'=>'counter_sales','purchase_bill'=>'purchase_bills','supplier_payment'=>'supplier_payments','customer_receipt'=>'customer_receipts','expense'=>'expenses','stock_adjustment'=>'stock_adjustments'];if(isset($map[$type]))Db::mustUpdate($db,Db::table($map[$type]),['status'=>'reversed'],['id'=>$id]);}
 private static function reverseCounterStock(Actor $a,int $id):void{$db=Db::wpdb();$sale=$db->get_row($db->prepare("SELECT * FROM ".Db::table('counter_sales')." WHERE id=%d AND company_id=%d AND status='posted'",$id,$a->companyId),ARRAY_A);if(!$sale)throw new DomainException('Posted Counter Sale not found.');$allocated=(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM ".Db::table('customer_receipts')." WHERE sale_id=%d AND company_id=%d AND status='posted'",$id,$a->companyId));if($allocated)throw new DomainException('Reverse allocated customer receipts before sale.','dependent_receipt_exists',409);foreach((array)$db->get_results($db->prepare("SELECT * FROM ".Db::table('counter_sale_lines')." WHERE sale_id=%d",$id),ARRAY_A) as$l)StockService::move($a,(int)$sale['branch_id'],(int)$l['product_id'],$l['batch_id']!==null?(int)$l['batch_id']:null,null,'IN',(float)$l['quantity'],(float)$l['purchase_cost_snapshot'],'counter_sale_reversal',$id);}
 private static function reversePurchaseStock(Actor $a,int $id):void{$db=Db::wpdb();$bill=$db->get_row($db->prepare("SELECT * FROM ".Db::table('purchase_bills')." WHERE id=%d AND company_id=%d AND status='posted'",$id,$a->companyId),ARRAY_A);if(!$bill)throw new DomainException('Posted Purchase Bill not found.');if((float)$bill['paid_amount']>0)throw new DomainException('Reverse supplier payments before purchase bill.','dependent_payment_exists',409);foreach((array)$db->get_results($db->prepare("SELECT * FROM ".Db::table('purchase_bill_lines')." WHERE purchase_bill_id=%d",$id),ARRAY_A) as$l)StockService::move($a,(int)$bill['branch_id'],(int)$l['product_id'],$l['batch_id']!==null?(int)$l['batch_id']:null,null,'OUT',(float)$l['quantity'],(float)$l['unit_cost'],'purchase_bill_reversal',$id);}
 private static function reverseSupplierPayment(Actor $a,int $id):void{$db=Db::wpdb();$t=Db::table('supplier_payments');$p=$db->get_row($db->prepare("SELECT * FROM {$t} WHERE id=%d AND company_id=%d AND status='posted' FOR UPDATE",$id,$a->companyId),ARRAY_A);if(!$p)throw new DomainException('Posted Supplier Payment not found.');Db::mustQuery($db,$db->prepare("UPDATE ".Db::table('purchase_bills')." SET paid_amount=paid_amount-%f,outstanding_amount=outstanding_amount+%f WHERE id=%d",(float)$p['amount'],(float)$p['amount'],(int)$p['purchase_bill_id']));}
 private static function reverseCustomerReceipt(Actor $a,int $id):void{$db=Db::wpdb();$t=Db::table('customer_receipts');$r=$db->get_row($db->prepare("SELECT * FROM {$t} WHERE id=%d AND company_id=%d AND status='posted' FOR UPDATE",$id,$a->companyId),ARRAY_A);if(!$r)throw new DomainException('Posted Customer Receipt not found.');$sale=$db->get_row($db->prepare("SELECT id,paid_amount,outstanding_amount FROM ".Db::table('counter_sales')." WHERE id=%d AND company_id=%d AND status='posted' FOR UPDATE",(int)$r['sale_id'],$a->companyId),ARRAY_A);if(!$sale)throw new DomainException('Receipt source sale is not posted.','receipt_sale_state_invalid',409);$amount=(float)$r['amount'];if((float)$sale['paid_amount']+.005<$amount)throw new DomainException('Receipt reversal would make sale payment invalid.','receipt_reversal_invalid',409);Db::mustQuery($db,$db->prepare("UPDATE ".Db::table('counter_sales')." SET paid_amount=paid_amount-%f,outstanding_amount=outstanding_amount+%f WHERE id=%d",$amount,$amount,(int)$r['sale_id']));}
 private static function reverseStockAdjustment(Actor $a,int $adjustmentId,int $reversalId):void{$db=Db::wpdb();$h=Db::table('stock_adjustments');$r=$db->get_row($db->prepare("SELECT * FROM {$h} WHERE id=%d AND company_id=%d AND status='approved' FOR UPDATE",$adjustmentId,$a->companyId),ARRAY_A);if(!$r)throw new DomainException('Approved Stock Adjustment not found.','adjustment_not_found',404);$lines=(array)$db->get_results($db->prepare("SELECT * FROM ".Db::table('stock_adjustment_lines')." WHERE adjustment_id=%d ORDER BY id",$adjustmentId),ARRAY_A);foreach($lines as$l){$d=(float)$l['quantity_delta'];$batch=$l['batch_id']!==null?(int)$l['batch_id']:null;$cost=(float)$l['unit_cost_snapshot'];StockService::move($a,(int)$r['branch_id'],(int)$l['product_id'],$batch,null,$d>0?'OUT':'IN',abs($d),$cost,'stock_adjustment_reversal',$reversalId);}}
 private static function reverseDailyCycle(Actor $a,int $cycleId,int $reversalId):void{$db=Db::wpdb();$c=$db->get_row($db->prepare("SELECT * FROM ".Db::table('daily_cycles')." WHERE id=%d AND company_id=%d AND status='completed' FOR UPDATE",$cycleId,$a->companyId),ARRAY_A);if(!$c)throw new DomainException('Completed Daily Order not found.');$closed=(string)$db->get_var($db->prepare("SELECT status FROM ".Db::table('branch_closings')." WHERE company_id=%d AND branch_id=%d AND business_date=%s",$a->companyId,(int)$c['branch_id'],$c['business_date']));if($closed==='closed')throw new DomainException('Reopen Branch Closing before Daily Order correction.','branch_day_closed',409);$e=$db->get_row($db->prepare("SELECT * FROM ".Db::table('evening_settlements')." WHERE daily_cycle_id=%d FOR UPDATE",$cycleId),ARRAY_A);if(!$e||$e['status']!=='posted')throw new DomainException('Posted Evening Settlement not found.');$lines=(array)$db->get_results($db->prepare("SELECT * FROM ".Db::table('evening_lines')." WHERE evening_settlement_id=%d",(int)$e['id']),ARRAY_A);foreach($lines as$l){$batch=$l['batch_id']!==null?(int)$l['batch_id']:null;$sold=(float)$l['retail_quantity']+(float)$l['wholesale_quantity'];$ret=(float)$l['return_quantity'];$cost=(float)$l['purchase_cost_snapshot'];if($sold>0)StockService::move($a,(int)$c['branch_id'],(int)$l['product_id'],$batch,(int)$c['employee_id'],'IN',$sold,$cost,'daily_sale_reversal',$reversalId);if($ret>0){StockService::move($a,(int)$c['branch_id'],(int)$l['product_id'],$batch,null,'OUT',$ret,$cost,'daily_return_reversal',$reversalId);StockService::move($a,(int)$c['branch_id'],(int)$l['product_id'],$batch,(int)$c['employee_id'],'IN',$ret,$cost,'daily_return_reversal',$reversalId);}}$points=(float)$db->get_var($db->prepare("SELECT COALESCE(SUM(points),0) FROM ".Db::table('performance_entries')." WHERE company_id=%d AND employee_id=%d AND source_type='daily_cycle' AND source_id=%d",$a->companyId,(int)$c['employee_id'],$cycleId));$salary=(float)$db->get_var($db->prepare("SELECT COALESCE(SUM(salary_fund),0) FROM ".Db::table('performance_entries')." WHERE company_id=%d AND employee_id=%d AND source_type='daily_cycle' AND source_id=%d",$a->companyId,(int)$c['employee_id'],$cycleId));Db::mustInsert($db,Db::table('performance_entries'),['company_id'=>$a->companyId,'branch_id'=>(int)$c['branch_id'],'employee_id'=>(int)$c['employee_id'],'business_date'=>$c['business_date'],'source_type'=>'daily_cycle_reversal','source_id'=>$reversalId,'points'=>-$points,'salary_fund'=>-$salary,'created_at'=>Db::now()]);Db::mustUpdate($db,Db::table('evening_settlements'),['status'=>'draft','cash_amount'=>0,'upi_amount'=>0,'submitted_by'=>null,'reviewed_by'=>null,'submitted_at'=>null,'reviewed_at'=>null],['id'=>(int)$e['id']]);Db::mustUpdate($db,Db::table('daily_cycles'),['status'=>'evening_draft','completed_at'=>null],['id'=>$cycleId]);}

